// Home Health Aide Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const BAL='Balduzzi, Homemaker Home Health Aide', HART='Leahy, Fuzy & Grafe, Providing Home Care';
const RESP='Responsibilities and Legal/Ethical Issues', COMM='Effective Communication', INF='Infection Control and Safety', BODY='Body Systems and Common Disorders', SPEC='Caring for Special Populations', SKILL='Basic Healthcare Skills';

export default {
 id:'home-health-aide-5',
 event:'Home Health Aide',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Balduzzi’s Homemaker Home Health Aide and Leahy, Fuzy & Grafe’s Providing Home Care',
 plan:[{area:RESP,weight:10},{area:COMM,weight:6},{area:INF,weight:10},{area:BODY,weight:40},{area:SPEC,weight:24},{area:SKILL,weight:10}],
 questions:mix([
  q(RESP,'Under federal rules, how many hours of training must a home health aide complete before working for a Medicare-certified agency?','At least 75 hours, including supervised practical training',['At least 5 hours of online videos only','At least 500 hours of classroom work in a hospital nursing program','No training is required for home care work'],'A','Federal rules require at least 75 hours of training, with at least 16 hours of supervised practical work, plus a competency test.',HART),
  q(RESP,'An aide writes on a time sheet that they worked 6 hours but actually worked 4. What is this?','Fraud',['Good time management','A charting shortcut that is allowed','Negligence'],'B','Falsifying time records to receive payment is fraud and can lead to firing and legal action.',HART),
  q(RESP,'A client offers to let the aide borrow her car to run personal errands. What should the aide do?','Politely decline, because using a client’s property for personal use is not allowed',['Accept, since the client offered freely and it saves the aide time between visits','Accept, but only for short trips','Accept and give the client gas money'],'C','Aides should not use client property, money or phones for personal reasons; it can lead to exploitation claims.',BAL),
  q(RESP,'How often does a registered nurse usually make a supervisory visit to check on a Medicare client’s home health aide services?','At least every 14 days',['Once a year','Only if the client complains','Every 6 months'],'D','Medicare requires RN supervisory visits for home health aide services at least every 14 days.',HART),
  q(RESP,'An aide posts a photo from a client’s home on social media without the client’s face. Why is this still a problem?','It may reveal the client’s identity or home and violates privacy',['It is allowed if the post is deleted later that day, before many people see it','It is required to show good work','It is only a problem if the client is famous'],'A','Details in photos can identify a client; aides must never share client information online.',HART),
  q(COMM,'A client says, “I feel so alone since my wife died.” Which response is a cliché that should be avoided?','“Time heals all wounds.”',['“Tell me more about how you are feeling.”','“It sounds like you miss her very much.”','“Would you like to talk about her?”'],'B','Clichés brush off feelings; listening and reflecting show care.',BAL),
  q(COMM,'When phoning the supervisor about a client’s change in condition, how should the aide report?','Briefly and accurately, stating facts and what was observed',['With guesses about the diagnosis','Only by sending a text the next day','By describing how the aide feels about the client'],'C','Clear, factual reports help the nurse decide what to do quickly.',BAL),
  q(COMM,'Two adult children argue in front of the aide about their mother’s care. What should the aide do?','Stay neutral and report the conflict to the supervisor',['Take the side of the child who seems nicer and more caring toward the mother','Join in and give the aide’s opinion','Tell the mother which child is right'],'D','Aides should not get involved in family disputes; the supervisor can address them.',BAL),
  q(INF,'At what temperature should a home refrigerator be kept?','40 °F (4 °C) or below',['50 °F (10 °C) or below','60 °F (16 °C) or below','32 °F (0 °C) or below for all foods'],'A','Cold temperatures slow bacterial growth; the freezer should be at 0 °F.',BAL),
  q(INF,'Leftover cooked food should be put in the refrigerator within what time?','Within 2 hours',['Within 8 hours','Within 24 hours','Any time before bed'],'B','Bacteria grow quickly between 40 °F and 140 °F, so food left out longer than 2 hours should be thrown away.',BAL),
  q(INF,'How should clothing soiled with body fluids be laundered?','Separately, in hot water with detergent, while wearing gloves',['With the family’s regular laundry in cold water','By shaking it out and hanging it outside','By soaking it in the bathtub with dishes'],'C','Handling soiled laundry carefully and separately prevents the spread of germs.',BAL),
  q(INF,'How often should smoke detectors in a client’s home usually be tested?','About once a month',['Once every 5 years','Only after a fire','Never, they test themselves'],'D','Batteries are usually replaced at least once a year or when the detector chirps.',BAL),
  q(INF,'Which bathroom change best helps prevent falls for an older client?','Installing grab bars near the toilet and tub',['Adding a soft, fluffy bath rug next to the tub and toilet for warmth','Using bath oil in the tub','Keeping the light off at night'],'A','Grab bars, nonslip mats and night-lights reduce bathroom falls.',BAL),
  q(BODY,'A client has a disease that gradually weakens the muscles, but thinking and memory stay intact. Which disease is this?','Amyotrophic lateral sclerosis (ALS)',['Alzheimer disease with memory loss','Down syndrome from an extra chromosome','Schizophrenia with hallucinations'],'B','ALS destroys motor neurons; clients may eventually need help with breathing and swallowing.',HART),
  q(BODY,'A client with a spinal cord injury has a pounding headache, sweating and very high blood pressure. What should the aide check first?','Whether the bladder is full or the catheter is kinked',['Whether the client wants a snack or something cold to drink before resting','Whether the TV is too loud','Whether the client needs a haircut'],'C','Autonomic dysreflexia is an emergency often caused by a full bladder; report it immediately.',HART),
  q(BODY,'A client’s legs cramp when walking and ease with rest, and the feet are cool and pale. What does this suggest?','Peripheral artery disease',['Deep vein thrombosis','Varicose veins','Gout'],'D','Narrowed leg arteries reduce blood flow during activity; foot care and wound monitoring are important.',HART),
  q(BODY,'A client has twisted, bulging veins in the legs. Which advice may help?','Elevate the legs and avoid standing in one place for long periods',['Cross the legs when sitting and stand still for long periods','Wear tight belts and garters','Massage the veins very firmly'],'A','Varicose veins come from weak valves; elevation and compression stockings improve blood return.',HART),
  q(BODY,'A client has a cough lasting weeks, night sweats, fever and weight loss. Which infection should be suspected?','Tuberculosis',['Asthma','Hay fever','Sinus headache'],'B','TB spreads through the air; report symptoms so the client can be evaluated.',HART),
  q(BODY,'A client uses a CPAP machine at night. What condition is it most often used to treat?','Obstructive sleep apnea',['Type 2 diabetes','Hypothyroidism (low thyroid)','Osteoarthritis of the knees'],'C','CPAP keeps the airway open with gentle air pressure; the mask should be cleaned as directed.',HART),
  q(BODY,'A client has rectal pain and bright red blood on toilet paper. What is a common cause?','Hemorrhoids',['Gallstones','Kidney stones','Appendicitis'],'D','Any rectal bleeding should be reported; straining and constipation make hemorrhoids worse.',HART),
  q(BODY,'A client has burning stomach pain and is being treated for H. pylori bacteria. Which condition is this?','A peptic ulcer',['A urinary tract infection','Diverticulosis','Hemorrhoids'],'A','Ulcers are sores in the stomach or duodenum; report black, tarry stools or vomiting blood.',HART),
  q(BODY,'Which change should be reported because it may be a warning sign of colon cancer?','A change in bowel habits or blood in the stool',['Regular daily bowel movements at about the same time each morning','Brown, formed stool','Passing gas after beans'],'B','Early reporting helps the nurse arrange evaluation and screening.',HART),
  q(BODY,'An older man has trouble starting urination and a weak stream. What is a common cause?','An enlarged prostate (BPH)',['A urinary tract infection in women','Kidney failure from dialysis','Low blood sugar'],'C','BPH presses on the urethra; report pain, fever or inability to urinate.',HART),
  q(BODY,'A client has sudden, severe pain in the side and back that comes in waves and blood in the urine. What may be the cause?','A kidney stone',['Heartburn','A tension headache','A sprained ankle'],'D','Kidney stones can block urine flow; report the pain and save any stone passed if instructed.',HART),
  q(BODY,'Why do clients with diabetes need regular eye exams?','High blood sugar can damage blood vessels in the retina',['Diabetes always causes color blindness in both eyes within the first year','Insulin makes the eyes itchy','Diabetes improves vision over time'],'A','Diabetic retinopathy can cause blindness; good blood sugar control and checkups help prevent it.',HART),
  q(BODY,'After a hip replacement, which movement should the client usually avoid?','Bending the hip more than 90 degrees',['Wiggling the toes','Lying on the back with a pillow between the legs','Using a raised toilet seat'],'B','Hip precautions prevent dislocation; avoid crossing the legs and low chairs as well.',HART),
  q(BODY,'A bedbound client’s joints are becoming permanently bent and stiff. What is this called?','Contractures',['Muscle spasms','Resting tremors','Ligament sprains'],'C','Regular range-of-motion exercises and positioning help prevent contractures.',HART),
  q(BODY,'An older client’s thin skin tears when bumped against a wheelchair. How can skin tears be prevented?','Pad sharp surfaces and use a lift sheet when moving the client',['Pull the client up in bed by the arms and wrists to move them quickly and smoothly','Use tape directly on fragile skin','Keep the skin dry by avoiding lotion'],'D','Gentle handling, padding and moisturizing protect fragile older skin.',HART),
  q(BODY,'A client’s lower leg is red, warm, swollen and tender, with a fever. What may this be?','Cellulitis, a skin infection',['A normal bruise','Sunburn','A healthy reaction to exercise'],'A','Cellulitis can spread quickly and must be reported for treatment.',HART),
  q(BODY,'After breast cancer surgery with lymph node removal, why is blood pressure not taken on that arm?','To lower the risk of swelling (lymphedema) and infection',['Because the pulse cannot be felt there','Because the arm has no blood vessels','Because it will always give a high reading'],'B','Avoid blood draws, tight sleeves and cuffs on the affected arm.',HART),
  q(BODY,'One side of a client’s face suddenly droops, but the client has no arm weakness or speech changes. What is one possible cause that still needs reporting?','Bell’s palsy',['Osteoarthritis','A sprain','Gout'],'C','Bell’s palsy affects a facial nerve, but sudden drooping must always be reported because it can also signal a stroke.',HART),
  q(BODY,'A woman in her early 50s has hot flashes and night sweats. What is a likely cause?','Menopause',['Puberty','Pregnancy','Appendicitis'],'D','Light layers, cool rooms and avoiding triggers can ease hot flashes.',HART),
  q(BODY,'Why is a client receiving chemotherapy at higher risk of infection?','Chemotherapy can lower the white blood cell count',['Chemotherapy raises the immune system too high','Chemotherapy kills only bacteria','Chemotherapy removes the need for hand hygiene'],'A','Careful hand hygiene and keeping sick visitors away help protect the client.',HART),
  q(SPEC,'How can an aide help a newborn release swallowed air after feeding?','Hold the baby upright on the shoulder and gently pat the back',['Lay the baby flat on the stomach and shake gently','Give the baby water in a bottle','Hold the baby upside down'],'B','Burping during and after feeding reduces fussiness and spitting up.',BAL),
  q(SPEC,'A breastfeeding mother is tired. Which support is most helpful?','Encourage plenty of fluids, healthy food and rest',['Encourage her to skip meals to lose weight','Tell her to stop breastfeeding immediately','Give her caffeine drinks all day'],'C','Breastfeeding increases fluid and calorie needs, so rest, water and healthy meals support the mother.',BAL),
  q(SPEC,'Two weeks after delivery, a new mother cries often, feels hopeless and is not interested in her baby. What should the aide do?','Report it, because this may be postpartum depression',['Ignore it, because this is normal baby blues','Tell her to cheer up for the baby','Take the baby to another home'],'D','Baby blues usually ease within 2 weeks; lasting or severe symptoms need evaluation.',BAL),
  q(SPEC,'How should an aide teach a new skill to a client with an intellectual disability?','Break it into small steps and practice with praise',['Explain every step at once in detail, then let the client try it alone','Do the task for the client every time','Give the client a written test first'],'A','Repetition, demonstration and encouragement help clients gain independence.',BAL),
  q(SPEC,'A child with autism becomes very upset when the aide changes the bath time. What would most help?','Keep a consistent daily routine and prepare the child for changes',['Change the routine every day so the child adjusts','Raise the voice so the child listens','Stop giving baths altogether'],'B','Many people with autism feel safer with predictable routines.',BAL),
  q(SPEC,'Which tool can help a client with early dementia remember daily tasks?','A large calendar and written checklist in a visible place',['Hiding the clocks and calendars','Changing the furniture often','Leaving many items out for the client to sort'],'C','Memory aids, labels and routines support independence in early dementia.',BAL),
  q(SPEC,'A dying client asks the aide, “Am I going to die soon?” What is the best response?','Listen, ask what is on their mind, and let the nurse know about the question',['Change the subject quickly to something cheerful so the client stops worrying about it','Say, “Don’t talk like that.”','Give a guess about how much time is left'],'D','Aides listen and offer support, then report so the nurse and team can respond.',BAL),
  q(SPEC,'A client with an anxiety disorder is breathing fast and says she feels panicked. What should the aide do?','Stay calm, speak softly and encourage slow breathing',['Leave the room until she calms down','Tell her there is nothing to worry about and change the topic','Turn on loud music to distract her'],'A','A calm presence and slow breathing help ease panic; report the episode.',BAL),
  q(SPEC,'A client sits in a wheelchair most of the day. How often should the client shift weight to relieve pressure?','About every 15 minutes',['About once every 8 hours','Only at bedtime','Only when the skin is already red'],'B','Frequent weight shifts protect the buttocks and tailbone from pressure injuries.',BAL),
  q(SPEC,'A client on chemotherapy has painful mouth sores. Which food is best?','Soft, cool foods such as yogurt or pudding',['Spicy chips and salsa for flavor','Crunchy toast and mixed nuts for protein','Orange juice and lemonade for vitamin C'],'C','Soft, bland, cool foods are easier to eat; acidic and spicy foods irritate sores.',BAL),
  q(SPEC,'An older client lives alone, wears dirty clothes and has spoiled food and unpaid bills piled up. What should the aide do?','Report possible self-neglect to the supervisor',['Ignore it because the client chose this','Throw away the client’s belongings','Move into the home to help'],'D','Self-neglect is a form of elder mistreatment; the agency can arrange help.',BAL),
  q(SPEC,'How can an aide respect the privacy of a teenage client?','Knock before entering and allow time alone when safe',['Read the teen’s messages to understand them','Share private details with the teen’s friends','Avoid explaining any care'],'A','Teens value privacy and independence; respect builds cooperation.',BAL),
  q(SKILL,'A client just drank hot coffee. How long should the aide wait before taking an oral temperature?','About 15 to 20 minutes',['No wait is needed','About 1 minute','About 2 hours'],'B','Hot or cold food and drinks and smoking can change oral temperature readings.',BAL),
  q(SKILL,'Where should the blood pressure cuff be placed on the arm?','About 1 inch above the elbow, with the arrow over the brachial artery',['Around the wrist, with the cuff left loose so it does not squeeze the client’s arm too tightly','Over the elbow joint','Below the elbow on the forearm'],'C','The bottom edge of the cuff sits about an inch above the elbow crease.',BAL),
  q(SKILL,'When making a bed, what is the purpose of a mitered corner?','It keeps the sheet tucked neatly and firmly in place',['It keeps the client from moving at all','It warms the bed faster','It makes it easier to remove the mattress'],'D','Neat, tight corners help prevent wrinkles that can cause skin breakdown.',BAL),
  q(SKILL,'Before giving a back rub, what should be done with the lotion?','Warm it in the hands or in warm water',['Chill it in the refrigerator','Mix it with rubbing alcohol','Apply it straight from a hot stove'],'A','Warm lotion is more comfortable and relaxing for the client; cold lotion can startle and chill them.',BAL),
  q(SKILL,'How should a client’s eyeglasses usually be cleaned?','With water or lens cleaner and a soft cloth',['With a dry paper towel and a little dish soap rubbed onto the lenses','With rubbing alcohol on a tissue','With the client’s shirt'],'B','Rough paper and harsh chemicals can scratch lenses and coatings.',BAL)
 ],9513)
};
